import random, subprocess, tempfile
from pathlib import Path
SAMPLE_IN = '3\n3 4\n.S..\n###.\n..E.\n3 4\n.S..\n.E..\n....\n3 4\n.S..\n####\n..E.\n'
SAMPLE_OUT = '5\n1\noop!\n'
CASES = ['3\n3 4\n.S..\n###.\n..E.\n3 4\n.S..\n.E..\n....\n3 4\n.S..\n####\n..E.\n', '1\n3 5\nS....\n.#...\n....E\n', '2\n4 7\nS......\n.....#.\n#......\n..##..E\n7 7\nS......\n.#.#...\n.###...\n.#..#..\n..#.#..\n..#....\n..#...E\n', '2\n4 9\nS........\n.#.......\n..#...#..\n#.......E\n9 8\nS.......\n....#...\n#..#....\n..#.....\n..#.....\n......#.\n##.##.#.\n........\n..#.#..E\n', '2\n3 6\nS.....\n##....\n#....E\n4 8\nS.......\n...#.#..\n..#..#..\n.#.#...E\n', '1\n4 3\nS..\n.#.\n...\n..E\n', '3\n8 5\nS....\n.#.#.\n..#..\n#....\n#....\n.....\n..#..\n#..#E\n3 8\nS.......\n.....#..\n....#..E\n9 7\nS......\n#......\n##.##..\n.......\n.......\n...#.#.\n....#..\n.....#.\n......E\n', '3\n9 6\nS.....\n......\n..#...\n..##..\n.#....\n...#..\n.#.##.\n..#...\n..#..E\n7 6\nS.....\n......\n......\n#.....\n.#....\n...#..\n.....E\n5 9\nS........\n......##.\n.........\n.....##..\n##......E\n', '1\n5 6\nS.....\n#.....\n##....\n#.#...\n.#...E\n', '3\n5 7\nS......\n#.#....\n.##....\n...#...\n...#.#E\n4 5\nS....\n#..#.\n.##..\n..#.E\n9 3\nS..\n##.\n...\n##.\n.#.\n.#.\n#..\n...\n..E\n', '3\n9 5\nS....\n...#.\n..#..\n.....\n..#..\n#.#..\n.....\n...#.\n.#.#E\n6 7\nS......\n.......\n.......\n#..##..\n.......\n.##...E\n9 4\nS...\n.#..\n.##.\n....\n..#.\n##..\n#...\n#...\n.#.E\n', '3\n9 8\nS.......\n#.......\n...#.##.\n..#.#...\n..#.....\n#.....#.\n..#...#.\n##.#....\n.#....#E\n5 8\nS.......\n.#......\n........\n.#.###..\n.......E\n4 6\nS.....\n#..#..\n.#.#..\n.#...E\n', '3\n4 6\nS.....\n#.#...\n....#.\n...#.E\n7 9\nS........\n..#.#....\n#....##..\n#.#..#...\n.....#...\n.....#...\n.#.#....E\n7 3\nS..\n#..\n...\n.#.\n##.\n...\n##E\n', '1\n9 5\nS....\n.....\n.#...\n...#.\n###..\n#....\n##.#.\n.#...\n...#E\n', '3\n4 4\nS...\n....\n.#..\n...E\n3 5\nS....\n#.#..\n....E\n4 8\nS.......\n.#.#....\n.##.....\n.......E\n', '3\n8 6\nS.....\n.#....\n...##.\n......\n......\n..#.#.\n.##.#.\n..###E\n5 6\nS.....\n....#.\n......\n#..#..\n....#E\n9 6\nS.....\n....#.\n.#....\n...#..\n......\n.#..#.\n#..##.\n..#.#.\n#...#E\n', '1\n3 5\nS....\n##...\n....E\n', '3\n3 8\nS.......\n..#.....\n.#.#...E\n5 7\nS......\n#..#...\n..##...\n...#...\n.#####E\n3 5\nS....\n.#...\n....E\n', '1\n8 3\nS..\n##.\n##.\n...\n##.\n...\n...\n..E\n', '2\n8 3\nS..\n...\n#..\n...\n...\n.#.\n#..\n..E\n3 3\nS..\n...\n..E\n']
REFERENCE_SOURCE = 'from collections import deque\n\ndef solve_maze():\n    T = int(input())\n    for _ in range(T):\n        R, C = map(int, input().split())\n        maze = [list(input().strip()) for _ in range(R)]\n\n        # 找起点 S\n        for i in range(R):\n            for j in range(C):\n                if maze[i][j] == \'S\':\n                    start = (i, j)\n                if maze[i][j] == \'E\':\n                    end = (i, j)\n\n        # BFS\n        queue = deque()\n        visited = [[False] * C for _ in range(R)]\n        queue.append((start[0], start[1], 0))  # (row, col, distance)\n        visited[start[0]][start[1]] = True\n\n        found = False\n\n        while queue:\n            x, y, dist = queue.popleft()\n            if (x, y) == end:\n                print(dist)\n                found = True\n                break\n\n            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:\n                nx, ny = x + dx, y + dy\n                if 0 <= nx < R and 0 <= ny < C:\n                    if not visited[nx][ny] and maze[nx][ny] != \'#\':\n                        visited[nx][ny] = True\n                        queue.append((nx, ny, dist + 1))\n\n        if not found:\n            print("oop!")\n\n# 调用主函数\nsolve_maze()\n'
assert CASES[0] == SAMPLE_IN
random.seed(7218)
def solve_reference(content):
    with tempfile.NamedTemporaryFile("w", suffix=".py", encoding="utf-8") as handle:
        handle.write(REFERENCE_SOURCE); handle.flush()
        result = subprocess.run(["python3", handle.name], input=content, text=True, capture_output=True, timeout=5, check=True)
    return result.stdout
assert solve_reference(SAMPLE_IN).split() == SAMPLE_OUT.split()
root = Path(__file__).parent / "data"
for index, content in enumerate(CASES):
    (root / f"{index}.in").write_text(content, encoding="utf-8")
    (root / f"{index}.out").write_text(solve_reference(content), encoding="utf-8")
